"""Generate a deterministic SYNTHETIC earlier-week snapshot for offline tests.

Reads the real ``data/json/2026-10-23.json`` snapshot, perturbs its prices
with a fixed seed, and writes ``2026-10-16.json`` with top-level
``"synthetic": true``. Also copies the real 2026-10-23 file into the same
directory so ``tests/fixtures/synthetic/`` is a self-contained 2-snapshot
data dir for tests.

The output is clearly labelled synthetic test data and must NEVER be placed
under ``data/json/``.

Usage (repo root)::

    .venv/bin/python tests/fixtures/synthetic/make_synthetic.py
"""

from __future__ import annotations

import argparse
import copy
import json
import os
import random
import shutil
import sys

SEED = 20261016
REAL_DATE = "2026-10-23"
SYNTHETIC_DATE = "2026-10-16"

NOTE = (
    "SYNTHETIC TEST DATA - generated by perturbing the real 2026-10-23 "
    "DA data; NOT real prices"
)

# Explicit (market, commodity) -> synthetic price overrides for the 4 focus
# markets. These create clear, hand-checkable week-over-week moves against
# the real 2026-10-23 snapshot (which acts as the "latest" week):
#   * Bangus / Las Pinas:        240.0  vs real 270.0  -> latest +12.5%
#   * Tomato / Las Pinas:        100.0  vs real 90.0   -> latest -10.0%
#   * Premium Rice (Imported) / Las Pinas: unchanged (59.0)
#   * Egg (Medium) / Las Pinas:  unchanged (8.5)
#   * Fresh Pork (Kasim) Local / Las Pinas: 240.0 vs real 260.0 -> +8.3%
#   * Red Onion (Local) / Las Pinas: 120.0 vs real 105.0 -> -12.5%
#   * Tilapia / Alabang:         145.0  vs real 160.0  -> latest +10.3%
#   * Premium Rice (Local) / Alabang: unchanged (54.0)
#   * Tomato / Alabang:          None   vs real 80.0   -> NULL in baseline week
#   * Bangus / La Huerta:        unchanged (260.0)
#   * Tilapia / La Huerta:       140.0  vs real 160.0  -> latest +14.3%
#   * Well-milled Rice (Imported) / La Huerta: 47.0 vs real None
#   *   -> NULL in the latest (real) week
#   * Galunggong (Local) / Bicutan: 230.0 vs real 200.0 -> latest -13.0%
#   * Egg (Medium) / Bicutan:    unchanged (8.5)
#   * Fresh Whole Chicken / Bicutan: 195.0 vs real 205.0 -> latest +5.1%
EXPLICIT_OVERRIDES: dict[tuple[str, str], float | None] = {
    ("New Las Piñas City Public Market", "Bangus"): 240.0,
    ("New Las Piñas City Public Market", "Tomato"): 100.0,
    ("New Las Piñas City Public Market", "Premium Rice (Imported)"): 59.0,
    ("New Las Piñas City Public Market", "Egg (Medium)"): 8.5,
    ("New Las Piñas City Public Market", "Fresh Pork (Kasim) Local"): 240.0,
    ("New Las Piñas City Public Market", "Red Onion (Local)"): 120.0,
    ("Alabang Central Market", "Tilapia"): 145.0,
    ("Alabang Central Market", "Premium Rice (Local)"): 54.0,
    ("Alabang Central Market", "Tomato"): None,
    ("La Huerta Market/Parañaque", "Bangus"): 260.0,
    ("La Huerta Market/Parañaque", "Tilapia"): 140.0,
    ("La Huerta Market/Parañaque", "Well-milled Rice (Imported)"): 47.0,
    ("Bicutan Market", "Galunggong (Local)"): 230.0,
    ("Bicutan Market", "Egg (Medium)"): 8.5,
    ("Bicutan Market", "Fresh Whole Chicken"): 195.0,
}

UP_PCTS = (5.0, 6.0, 8.0, 10.0, 12.0, 15.0)
DOWN_PCTS = (5.0, 7.0, 9.0, 11.0, 13.0, 15.0)


def perturb_price(rng: random.Random, price: float | None) -> float | None:
    """Deterministically perturb *price*; NULL stays NULL."""
    if price is None:
        return None
    roll = rng.random()
    if roll < 0.35:
        return price  # unchanged
    if roll < 0.65:
        pct = rng.choice(UP_PCTS)
        return round(price * (1.0 + pct / 100.0), 2)
    pct = rng.choice(DOWN_PCTS)
    return round(price * (1.0 - pct / 100.0), 2)


def make_synthetic(real: dict) -> dict:
    rng = random.Random(SEED)
    out = copy.deepcopy(real)
    out["date"] = SYNTHETIC_DATE
    out["source_url"] = None
    out["synthetic"] = True
    out["note"] = NOTE
    for market in sorted(out["markets"]):
        for commodity in sorted(out["markets"][market]):
            key = (market, commodity)
            if key in EXPLICIT_OVERRIDES:
                out["markets"][market][commodity]["price"] = EXPLICIT_OVERRIDES[key]
                continue
            entry = out["markets"][market][commodity]
            entry["price"] = perturb_price(rng, entry["price"])
    return out


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    here = os.path.dirname(os.path.abspath(__file__))
    repo_root = os.path.normpath(os.path.join(here, "..", "..", ".."))
    parser.add_argument(
        "--real",
        default=os.path.join(repo_root, "data", "json", f"{REAL_DATE}.json"),
        help="Path to the real snapshot to perturb",
    )
    parser.add_argument(
        "--out-dir", default=here, help="Directory for synthetic fixtures"
    )
    args = parser.parse_args(argv)

    with open(args.real, encoding="utf-8") as handle:
        real = json.load(handle)
    if real.get("synthetic"):
        print("error: input already looks synthetic; refusing", file=sys.stderr)
        return 1

    synthetic = make_synthetic(real)
    os.makedirs(args.out_dir, exist_ok=True)
    synth_path = os.path.join(args.out_dir, f"{SYNTHETIC_DATE}.json")
    with open(synth_path, "w", encoding="utf-8") as handle:
        json.dump(synthetic, handle, indent=2, ensure_ascii=False)
        handle.write("\n")
    # Copy the real snapshot so this directory is a self-contained
    # 2-snapshot data dir for tests.
    real_copy = os.path.join(args.out_dir, f"{REAL_DATE}.json")
    if os.path.abspath(args.real) != os.path.abspath(real_copy):
        shutil.copyfile(args.real, real_copy)
    print(synth_path)
    print(real_copy)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
